"""分析管线编排：参数校验 -> 读入 -> QC -> 归一化/HVG -> PCA -> 聚类 -> 差异表达 -> 写出。"""

from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union

from . import __version__
from .errors import CellFlowConfigError, CellFlowDataError
from .io import ExpressionMatrix, read_matrix
from .kmeans import kmeans
from .markers import find_group_markers, find_markers, find_pairwise_markers
from .metadata import read_metadata
from .mtx import read_mtx_directory
from .normalize import normalize_and_select_hvg
from .output import Artifacts, publish_results
from .pca import MAX_PCS, run_pca
from .qc import compute_qc
from .selection import select_cluster_count

DEFAULT_SEED = 20240617
AUTO = "auto"
FORMAT_TSV = "tsv"
FORMAT_MTX = "mtx"
INPUT_FORMATS = (FORMAT_TSV, FORMAT_MTX)


@dataclass(frozen=True)
class Config:
    input_path: str
    output_dir: str
    min_genes: int = 200
    max_mito_fraction: float = 0.2
    min_cells: int = 3
    mito_prefix: str = "MT-"
    n_hvg: int = 2000
    n_pcs: int = MAX_PCS
    n_clusters: Union[int, str] = 2
    seed: int = DEFAULT_SEED
    input_format: str = FORMAT_TSV
    metadata_path: Optional[str] = None

    @property
    def auto_clusters(self) -> bool:
        return self.n_clusters == AUTO

    def public_parameters(self) -> Dict[str, Any]:
        return {
            "min_genes": self.min_genes,
            "max_mito_fraction": self.max_mito_fraction,
            "min_cells": self.min_cells,
            "mito_prefix": self.mito_prefix,
            "n_hvg": self.n_hvg,
            "n_pcs": self.n_pcs,
            "n_clusters": self.n_clusters,
            "seed": self.seed,
        }


def validate_config(config: Config) -> None:
    """校验参数取值；冲突或非法一律抛 CellFlowConfigError。"""
    errors: List[str] = []
    if not isinstance(config.min_genes, int) or config.min_genes < 0:
        errors.append("--min-genes 必须是非负整数")
    if not isinstance(config.min_cells, int) or config.min_cells < 1:
        errors.append("--min-cells 必须是 >= 1 的整数")
    if (
        not isinstance(config.max_mito_fraction, (int, float))
        or isinstance(config.max_mito_fraction, bool)
        or not 0.0 <= float(config.max_mito_fraction) <= 1.0
    ):
        errors.append("--max-mito-fraction 必须是 [0, 1] 内的数值")
    if not isinstance(config.mito_prefix, str) or config.mito_prefix == "":
        errors.append("--mito-prefix 必须是非空字符串")
    if not isinstance(config.n_hvg, int) or config.n_hvg < 1:
        errors.append("--n-hvg 必须是 >= 1 的整数")
    if not isinstance(config.n_pcs, int) or config.n_pcs < 1:
        errors.append("--n-pcs 必须是 >= 1 的整数")
    if config.n_clusters != AUTO:
        if (
            not isinstance(config.n_clusters, int)
            or isinstance(config.n_clusters, bool)
            or config.n_clusters < 2
        ):
            errors.append("--n-clusters 必须是 >= 2 的整数")
    if not isinstance(config.seed, int) or isinstance(config.seed, bool):
        errors.append("--seed 必须是整数")
    if config.input_format not in INPUT_FORMATS:
        errors.append("--input-format 只能是 tsv 或 mtx")
    if errors:
        raise CellFlowConfigError("；".join(errors))


def run(config: Config) -> List[str]:
    validate_config(config)

    # 先完成读入与全部计算，最后再触碰输出目录：
    # 任何分析阶段失败都不应留下空目录或半成品结果
    if config.input_format == FORMAT_MTX:
        matrix = read_mtx_directory(config.input_path)
    else:
        matrix = read_matrix(config.input_path)

    # 元数据属于输入：先完成读取与校验，任何不合法都在触碰输出目录之前失败
    metadata = None
    if config.metadata_path is not None:
        metadata = read_metadata(config.metadata_path, matrix.cell_ids)

    qc = compute_qc(
        matrix,
        min_genes=config.min_genes,
        max_mito_fraction=config.max_mito_fraction,
        min_cells=config.min_cells,
        mito_prefix=config.mito_prefix,
    )

    n_kept_cells = len(qc.kept_cells)
    if n_kept_cells < 2:
        raise CellFlowDataError(
            f"质控后仅保留 {n_kept_cells} 个细胞，不足两个，无法分析"
        )
    if not qc.kept_genes:
        raise CellFlowDataError(
            f"没有基因在至少 {config.min_cells} 个细胞中检出，无可用基因"
        )

    if metadata is not None:
        kept_groups = {
            metadata.groups[matrix.cell_ids[c]] for c in qc.kept_cells
        }
        if len(kept_groups) < 2:
            raise CellFlowDataError(
                f"质控后非空分组仅 {len(kept_groups)} 个，不足两个，"
                f"无法进行分组差异表达"
            )

    if config.auto_clusters:
        # 自动模式：候选 k=2..min(10, 质控后细胞数)，PCA 后逐个评估
        normalized = normalize_and_select_hvg(matrix, qc, n_hvg=config.n_hvg)
        if not normalized.selected_genes:
            raise CellFlowDataError("高变基因选择结果为空，PCA 无法成立")

        try:
            pca = run_pca(normalized, config.n_pcs)
        except ValueError as exc:
            raise CellFlowDataError(f"PCA 无法成立：{exc}") from exc

        selection = select_cluster_count(pca.scores, config.seed)
        if selection is None:
            upper = min(10, n_kept_cells)
            raise CellFlowDataError(
                f"簇数自动选择失败：候选范围 k=2..{upper} 内无法形成两个以上"
                f"不同簇（方差不足）"
            )
        clustering = selection.clustering
    else:
        if config.n_clusters > n_kept_cells:
            raise CellFlowDataError(
                f"簇数 {config.n_clusters} 大于质控后细胞数 {n_kept_cells}，聚类无法成立"
            )

        normalized = normalize_and_select_hvg(matrix, qc, n_hvg=config.n_hvg)
        if not normalized.selected_genes:
            raise CellFlowDataError("高变基因选择结果为空，PCA 无法成立")

        try:
            pca = run_pca(normalized, config.n_pcs)
        except ValueError as exc:
            raise CellFlowDataError(f"PCA 无法成立：{exc}") from exc

        try:
            clustering = kmeans(pca.scores, config.n_clusters, config.seed)
        except ValueError as exc:
            raise CellFlowDataError(f"聚类无法成立：{exc}") from exc

        n_found_clusters = len(set(clustering.labels))
        if n_found_clusters < config.n_clusters:
            # 例如全部细胞表达相同：中心必然重合，无法形成 k 个不同簇
            raise CellFlowDataError(
                f"聚类无法成立：请求 {config.n_clusters} 个簇，"
                f"但数据仅能支撑 {n_found_clusters} 个不同簇（方差不足）"
            )
        selection = None

    markers = find_markers(normalized, clustering.labels)

    # 能执行到此处说明实际簇数 >= 2（上方已对不足两簇的数据错误拒绝），
    # 成对比较覆盖实际出现标签的全部 a < b 组合
    pairwise_markers = find_pairwise_markers(normalized, clustering.labels)

    # 分组差异表达：只用质控后保留细胞与基因的 log 归一化表达
    group_markers = None
    if metadata is not None:
        cell_groups = [metadata.groups[cell_id] for cell_id in normalized.cell_ids]
        group_markers = find_group_markers(normalized, cell_groups)

    cluster_sizes: Dict[int, int] = {}
    for label in clustering.labels:
        cluster_sizes[label] = cluster_sizes.get(label, 0) + 1

    input_info: Dict[str, Any] = {
        "path": matrix.path,
        "sha256": matrix.sha256,
        "n_genes": matrix.n_genes,
        "n_cells": matrix.n_cells,
        "total_counts": matrix.total_counts,
    }
    if matrix.input_format == FORMAT_MTX:
        # mtx 运行仅额外记录格式与三个输入文件的来源；tsv 运行字段保持不变
        input_info["input_format"] = FORMAT_MTX
        input_info["files"] = [
            {"name": f.name, "sha256": f.sha256} for f in matrix.files
        ]
    if metadata is not None:
        # 仅记录元数据来源与分组规模；既有 input 字段保持不变
        input_info["metadata"] = {
            "name": metadata.name,
            "sha256": metadata.sha256,
            "group_sizes": metadata.group_sizes,
        }

    run_info: Dict[str, Any] = {
        "version": __version__,
        "input": input_info,
        "parameters": config.public_parameters(),
        "stage_counts": {
            "input_cells": matrix.n_cells,
            "input_genes": matrix.n_genes,
            "cells_after_qc": n_kept_cells,
            "genes_after_qc": len(qc.kept_genes),
            "cells_filtered_out": matrix.n_cells - n_kept_cells,
            "genes_filtered_out": matrix.n_genes - len(qc.kept_genes),
            "highly_variable_genes": len(normalized.selected_genes),
            "max_pcs_parameter": MAX_PCS,
            "pcs": pca.n_pcs,
            # auto 模式下为选中的 k；显式模式下与请求簇数一致
            "clusters": (
                selection.selected_k if selection is not None
                else len(cluster_sizes)
            ),
            "cluster_sizes": [cluster_sizes[k] for k in sorted(cluster_sizes)],
            "marker_tests": len(markers) * len(qc.kept_genes),
            "kmeans_iterations": clustering.iterations,
        },
        "random_seed": config.seed,
    }

    artifacts = Artifacts(
        qc=qc,
        data=normalized,
        pca=pca,
        clustering=clustering,
        markers=markers,
        pairwise_markers=pairwise_markers,
        run_info=run_info,
        cluster_selection=selection,
        group_markers=group_markers,
    )
    # 全部计算已完成才触碰文件系统：预检与写出都在 publish_results 内，
    # 任一分析阶段失败时不会创建或改动目标目录；写出阶段任何文件系统故障
    # 都回滚暂存并抛 OutputPathError。
    return publish_results(config.output_dir, artifacts)

"""细胞分组元数据读取与严格校验。

``--metadata`` 指向 UTF-8 制表符文本，表头恰为 ``cell_id`` 与 ``group``
两列；``cell_id`` 唯一且与表达矩阵的全部细胞一一对应，``group`` 非空。
文件可为纯文本或单成员 gzip（按 gzip 魔数识别，与文件名无关）。
任何不合法（表头不符、ID 重复、覆盖不全、多出矩阵之外的细胞、空分组，
或 gzip 多成员、尾随数据、截断、校验失败）都抛
:class:`cell_flow.errors.CellFlowInputError`，且不改动任何已有结果。
"""

import hashlib
import os
from dataclasses import dataclass
from typing import Dict, List

from .errors import CellFlowInputError
from .io import GZIP_MAGIC, gunzip_single


@dataclass(frozen=True)
class CellMetadata:
    """细胞分组：每个矩阵细胞恰好归属一个非空分组。"""

    path: str
    name: str                  # 文件名（路径末段）
    sha256: str                # 原始字节（gzip 即压缩字节）的 SHA-256
    groups: Dict[str, str]     # cell_id -> group
    group_sizes: Dict[str, int]  # group -> 细胞数（按 group 升序）


def _fail(message: str) -> None:
    raise CellFlowInputError(message)


def read_metadata(path: str, cell_ids: List[str]) -> CellMetadata:
    """读取并校验分组元数据；``cell_ids`` 为表达矩阵的全部细胞 ID（列序）。"""
    if path is None or path == "":
        _fail("元数据路径为空")
    if not os.path.exists(path):
        _fail(f"元数据文件不存在：{path}")
    if not os.path.isfile(path):
        _fail(f"元数据路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"元数据文件不可读：{path}")

    # SHA-256 始终按磁盘上的实际原始字节计算（gzip 即压缩字节）
    try:
        with open(path, "rb") as handle:
            raw_bytes = handle.read()
    except OSError as exc:
        _fail(f"元数据文件不可读：{path}（{exc}）")

    digest = hashlib.sha256(raw_bytes).hexdigest()
    if raw_bytes[:2] == GZIP_MAGIC:
        text_bytes = gunzip_single(raw_bytes, path)
    else:
        text_bytes = raw_bytes
    try:
        text = text_bytes.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"元数据文件不是合法的 UTF-8 文本：{path}")

    # splitlines 同时兼容 \n 与 \r\n，且不会因末尾换行产生空行
    lines = text.splitlines()
    if not lines:
        _fail("元数据表头缺失：文件为空")
    header = lines[0].split("\t")
    if header != ["cell_id", "group"]:
        _fail("元数据表头必须恰为 cell_id 和 group 两列")

    groups: Dict[str, str] = {}
    for offset, line in enumerate(lines[1:], start=2):
        if line == "":
            _fail(f"元数据第 {offset} 行为空，无法解析")
        fields = line.split("\t")
        if len(fields) != 2:
            _fail(
                f"元数据第 {offset} 行列数为 {len(fields)}，与表头两列不一致"
            )
        cell_id, group = fields
        if cell_id == "":
            _fail(f"元数据第 {offset} 行细胞 ID 为空")
        if group == "":
            _fail(f"元数据第 {offset} 行分组为空（细胞 {cell_id!r}）")
        if cell_id in groups:
            _fail(f"元数据细胞 ID 重复：{cell_id!r}")
        groups[cell_id] = group

    missing = [cell_id for cell_id in cell_ids if cell_id not in groups]
    if missing:
        _fail(
            f"元数据未覆盖矩阵全部细胞：缺少 {missing[0]!r} "
            f"等 {len(missing)} 个"
        )
    matrix_cells = set(cell_ids)
    extra = [cell_id for cell_id in groups if cell_id not in matrix_cells]
    if extra:
        _fail(
            f"元数据包含矩阵之外的细胞：{extra[0]!r} 等 {len(extra)} 个"
        )

    sizes: Dict[str, int] = {}
    for group in groups.values():
        sizes[group] = sizes.get(group, 0) + 1
    group_sizes = {group: sizes[group] for group in sorted(sizes)}

    return CellMetadata(
        path=path,
        name=os.path.basename(path),
        sha256=digest,
        groups=groups,
        group_sizes=group_sizes,
    )

"""Cell Flow 的异常体系与对应退出码。"""


class CellFlowError(Exception):
    """所有 Cell Flow 受控错误的基类，携带确定退出码。"""

    exit_code = 1


class CellFlowInputError(CellFlowError):
    """输入矩阵不合法（空路径、不可读、表头缺失、ID 重复、空矩阵、非法计数）。"""

    exit_code = 2


class CellFlowConfigError(CellFlowError):
    """命令行参数冲突或取值非法。"""

    exit_code = 3


class CellFlowDataError(CellFlowError):
    """数据无法支撑分析（质控后细胞不足、无可用基因、PCA/聚类无法成立）。"""

    exit_code = 4


class OutputPathError(CellFlowError):
    """结果目录已存在且非空。"""

    exit_code = 5

"""输入矩阵读取与严格校验。

输入为制表符分隔矩阵：首列是唯一基因 ID，其余列名是唯一细胞 ID，
取值为非负整数 UMI 计数。文件承载方式有两种：UTF-8 制表符纯文本，
或其单成员 gzip 压缩文件（按 gzip 魔数自动识别，与文件名无关）。
任何不合法情形（含 gzip 头、CRC、长度校验失败、截断、多成员或
尾随数据）都抛出 :class:`cell_flow.errors.CellFlowInputError`。
"""

import hashlib
import os
import re
import zlib
from dataclasses import dataclass, field
from typing import List

from .errors import CellFlowInputError

_INTEGER_RE = re.compile(r"^(0|[1-9][0-9]*)$")

GZIP_MAGIC = b"\x1f\x8b"


@dataclass(frozen=True)
class InputFile:
    """一个输入文件的来源记录：文件名与原始字节的 SHA-256。"""

    name: str
    sha256: str


@dataclass(frozen=True)
class ExpressionMatrix:
    """原始计数矩阵（行＝基因，列＝细胞）。

    ``input_format`` 为 ``"tsv"`` 时沿用 ``path``/``sha256`` 单一文件记录
    （gzip 载体的 SHA-256 按压缩字节计算）；为 ``"mtx"`` 时 ``files`` 依次
    记录 matrix、barcodes、features 的实际文件名（含 ``.gz`` 后缀时亦然）
    与各自原始字节的 SHA-256。
    """

    gene_ids: List[str]
    cell_ids: List[str]
    counts: List[List[int]]  # counts[gene_index][cell_index]
    sha256: str
    path: str
    total_counts: int
    input_format: str = "tsv"
    files: List[InputFile] = field(default_factory=list)

    @property
    def n_genes(self) -> int:
        return len(self.gene_ids)

    @property
    def n_cells(self) -> int:
        return len(self.cell_ids)


def _fail(message: str) -> None:
    raise CellFlowInputError(message)


def gunzip_single(raw: bytes, path: str) -> bytes:
    """严格解压单成员 gzip 字节流。

    zlib 在 gzip 模式下对两类损坏静默：流尾截断（不返回错误，仅令
    ``eof`` 为假）与流后多余字节（放入 ``unused_data``）；而 CRC32 与
    ISIZE 不符会直接抛错。这里补齐前两项检查，并显式拒绝多成员
    （``unused_data`` 以 gzip 魔数开头即第二个成员）和任何尾随数据，
    确保流能被无损、无歧义地还原。
    """
    if len(raw) < 2 or raw[:2] != GZIP_MAGIC:
        _fail(f"gzip 头不合法：{path}（缺少魔数 {GZIP_MAGIC!r}）")
    decompressor = zlib.decompressobj(16 + zlib.MAX_WBITS)
    try:
        payload = decompressor.decompress(raw)
        payload += decompressor.flush()
    except zlib.error as exc:
        # 涵盖错误的压缩方法/标志、损坏的 deflate 数据、CRC32 与长度不符等
        _fail(f"gzip 数据无法无损还原：{path}（{exc}）")
    if not decompressor.eof:
        _fail(f"gzip 数据被截断或缺少完整尾部：{path}")
    if decompressor.unused_data:
        if decompressor.unused_data[:2] == GZIP_MAGIC:
            _fail(f"gzip 包含多个成员，仅允许单成员：{path}")
        _fail(f"gzip 流后存在尾随数据，仅允许单成员：{path}")
    return payload


def _parse_count(raw: str, gene_id: str, cell_id: str, row_no: int) -> int:
    if not _INTEGER_RE.match(raw):
        _fail(
            f"计数非法（第 {row_no} 行基因 {gene_id!r}、细胞 {cell_id!r}）："
            f"{raw!r} 不是非负整数"
        )
    return int(raw)


def read_matrix(path: str) -> ExpressionMatrix:
    if path is None or path == "":
        _fail("输入路径为空")
    if not os.path.exists(path):
        _fail(f"输入文件不存在：{path}")
    if not os.path.isfile(path):
        _fail(f"输入路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"输入文件不可读：{path}")

    # SHA-256 始终按磁盘上的实际原始字节计算（gzip 即压缩字节），
    # 解析则基于解压后的文本；两者承载方式不同时矩阵内容一致。
    try:
        with open(path, "rb") as handle:
            raw_bytes = handle.read()
    except OSError as exc:
        _fail(f"输入文件不可读：{path}（{exc}）")

    digest = hashlib.sha256(raw_bytes).hexdigest()
    if raw_bytes[:2] == GZIP_MAGIC:
        text_bytes = gunzip_single(raw_bytes, path)
    else:
        text_bytes = raw_bytes
    try:
        text = text_bytes.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"输入文件不是合法的 UTF-8 文本：{path}")

    # splitlines 同时兼容 \n 与 \r\n，且不会因末尾换行产生空行
    lines = text.splitlines()
    if not lines:
        _fail("表头缺失：文件为空")

    header = lines[0].split("\t")
    if len(header) < 2:
        _fail("表头缺失：至少需要基因 ID 列与一个细胞 ID 列")
    cell_ids = header[1:]
    if any(cell == "" for cell in cell_ids):
        _fail("表头存在空细胞 ID")
    if len(set(cell_ids)) != len(cell_ids):
        dup = _first_duplicate(cell_ids)
        _fail(f"细胞 ID 重复：{dup!r}")

    gene_ids: List[str] = []
    counts: List[List[int]] = []
    seen_genes = set()
    n_cells = len(cell_ids)

    for offset, line in enumerate(lines[1:], start=2):
        if line == "":
            _fail(f"第 {offset} 行为空，无法解析")
        fields = line.split("\t")
        if len(fields) != n_cells + 1:
            _fail(
                f"第 {offset} 行列数为 {len(fields) - 1}，"
                f"与表头细胞数 {n_cells} 不一致"
            )
        gene_id = fields[0]
        if gene_id == "":
            _fail(f"第 {offset} 行基因 ID 为空")
        if gene_id in seen_genes:
            _fail(f"基因 ID 重复：{gene_id!r}")
        seen_genes.add(gene_id)
        row = [
            _parse_count(fields[c + 1], gene_id, cell_ids[c], offset)
            for c in range(n_cells)
        ]
        gene_ids.append(gene_id)
        counts.append(row)

    if not gene_ids:
        _fail("空矩阵：没有任何基因数据行")

    total = 0
    for row in counts:
        total += sum(row)

    return ExpressionMatrix(
        gene_ids=gene_ids,
        cell_ids=cell_ids,
        counts=counts,
        sha256=digest,
        path=path,
        total_counts=total,
    )


def _first_duplicate(values: List[str]) -> str:
    seen = set()
    for value in values:
        if value in seen:
            return value
        seen.add(value)
    return values[0]

"""标准 10x MatrixMarket 稀疏输入读取与严格校验。

输入目录须含三个文件，每个文件可保持原名，也可整体改用 gzip 压缩名
（三个文件必须同为未压缩或同为 gzip，混用报输入错误）：
- ``matrix.mtx`` / ``matrix.mtx.gz``：MatrixMarket 坐标格式，仅接受
  ``coordinate integer general`` 或 ``coordinate real general``；
  行是基因、列是细胞、索引从 1 开始；零值可省略，显式值必须能
  无损解析为有限非负整数；
- ``barcodes.tsv`` / ``barcodes.tsv.gz``：每个非空行是一个细胞 ID，
  按文件行序进入分析；
- ``features.tsv`` / ``features.tsv.gz``：每个非空数据行取第一列作为
  基因 ID，按文件行序进入分析。

gzip 载体仅允许单成员且无尾随数据；gzip 头、CRC、长度校验失败或流被
截断一律报输入错误。声明维度必须与 ID 数量匹配；缺文件、两种文件名
并存、格式头不支持、越界索引、重复坐标、空或重复 ID、非法数值一律
抛 :class:`cell_flow.errors.CellFlowInputError`。
"""

import hashlib
import os
from decimal import Decimal, InvalidOperation
from typing import Dict, List, Optional, Tuple

from .errors import CellFlowInputError
from .io import GZIP_MAGIC, ExpressionMatrix, InputFile, gunzip_single

MATRIX_NAME = "matrix.mtx"
BARCODES_NAME = "barcodes.tsv"
FEATURES_NAME = "features.tsv"
GZIP_SUFFIX = ".gz"

_BANNER = "%%matrixmarket"


def _fail(message: str):
    raise CellFlowInputError(message)


def _resolve_name(directory: str, base_name: str) -> Tuple[str, bool]:
    """在目录中解析 ``<name>`` 或 ``<name>.gz``，二者必须恰好存在一个。

    返回（实际文件名，是否 gzip）。此步只做布局校验，不读取文件内容，
    以保证缺文件与“压缩/未压缩混用”的报错先于任何内容损坏报错。
    """
    gz_name = base_name + GZIP_SUFFIX
    plain_path = os.path.join(directory, base_name)
    gz_path = os.path.join(directory, gz_name)
    plain_exists = os.path.exists(plain_path)
    gz_exists = os.path.exists(gz_path)
    if plain_exists and gz_exists:
        _fail(
            f"MTX 输入同时存在 {base_name} 与 {gz_name}，"
            f"二者只能保留其一：{directory}"
        )
    if gz_exists:
        return gz_name, True
    if plain_exists:
        return base_name, False
    _fail(f"MTX 输入缺少文件：{plain_path}（或 {gz_name}）")


def _read_named_file(
    directory: str, name: str, *, compressed: bool
) -> Tuple[bytes, str]:
    path = os.path.join(directory, name)
    if not os.path.isfile(path):
        _fail(f"MTX 输入路径不是普通文件：{path}")
    if not os.access(path, os.R_OK):
        _fail(f"MTX 输入文件不可读：{path}")
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except OSError as exc:
        _fail(f"MTX 输入文件不可读：{path}（{exc}）")

    if compressed:
        # .gz 是压缩状态的显式声明：内容必须确实是 gzip，由
        # gunzip_single 严格校验魔数、CRC、长度、截断与单成员
        payload = gunzip_single(raw, path)
    elif raw[:2] == GZIP_MAGIC:
        # 未压缩名下出现 gzip 字节属于布局不合法，避免静默按内容嗅探
        _fail(
            f"MTX 输入文件 {name} 的内容是 gzip，但文件名未带 "
            f"{GZIP_SUFFIX} 后缀：{path}"
        )
    else:
        payload = raw

    try:
        text = payload.decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"MTX 输入文件不是合法的 UTF-8 文本：{path}")
    return raw, text


def _read_id_lines(
    text: str,
    path: str,
    *,
    first_column_only: bool,
    kind: str,
) -> List[str]:
    """读取 ID 列表。

    barcodes：每个非空行整体是一个细胞 ID；
    features：每个非空数据行取第一列作为基因 ID。
    空行跳过，空 ID 与重复 ID 均非法。ID 按文件行序排列。
    """
    ids: List[str] = []
    seen = set()
    for line_no, line in enumerate(text.splitlines(), start=1):
        if line == "":
            continue
        token = line.split("\t", 1)[0] if first_column_only else line
        if token == "":
            _fail(f"{path} 第 {line_no} 行{kind} ID 为空")
        if token in seen:
            _fail(f"{kind} ID 重复：{token!r}")
        seen.add(token)
        ids.append(token)
    return ids


def _parse_nonnegative_integer(
    token: str, field_type: str, entry_no: int
) -> Optional[int]:
    """把一个显式矩阵元素解析为有限非负整数，要求无损。

    integer 字段只接受十进制非负整数字面量；real 字段接受浮点写法，
    但数值必须有限、非负且与其取整结果严格相等（无损）。
    返回 None 表示该元素是可省略的零。
    """
    if field_type == "integer":
        if not _is_decimal_uint(token):
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是非负整数"
            )
        value = int(token)
    else:  # real
        # 用 Decimal 精确解析，避免经 float64 在 2^53 以上发生舍入而
        # 破坏“无损”；显式值必须有限、非负且恰为整数
        try:
            number = Decimal(token)
        except InvalidOperation:
            number = Decimal("nan")
        if not number.is_finite():
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是有限数值"
            )
        if number < 0:
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} 为负数"
            )
        if number != number.to_integral_value():
            _fail(
                f"{MATRIX_NAME} 第 {entry_no} 个数据元素 {token!r} "
                f"不是整数值，无法无损解析为计数"
            )
        value = int(number)
    if value == 0:
        return None
    return value


def _is_decimal_uint(token: str) -> bool:
    if not token:
        return False
    # 拒绝前导符号、小数点、指数、空白等；仅接受 0 或非零开头的十进制数
    if token == "0":
        return True
    if token[0] == "0" or not token[0].isdigit():
        return False
    return all(ch.isdigit() for ch in token)


def _parse_matrix(
    text: str, path: str
) -> Tuple[int, int, Dict[Tuple[int, int], int]]:
    lines = text.splitlines()

    # 1) 校验 banner 头
    if not lines:
        _fail(f"{path} 为空，缺少 MatrixMarket 头部")
    header_tokens = lines[0].split()
    if not header_tokens or header_tokens[0].lower() != _BANNER:
        _fail(
            f"{path} 格式头不支持：首行必须以 {_BANNER!r} 开头，"
            f"得到 {lines[0]!r}"
        )
    header = [t.lower() for t in header_tokens]
    # 标准 object/format/field/symmetry 五个关键字
    if len(header) != 5:
        _fail(f"{path} 格式头不支持：关键字数量不是 5：{lines[0]!r}")
    _, object_, format_, field_type, symmetry = header
    if object_ != "matrix":
        _fail(f"{path} 格式头不支持：object 必须是 matrix，得到 {object_!r}")
    if format_ != "coordinate":
        _fail(
            f"{path} 格式头不支持：仅接受 coordinate 格式，得到 {format_!r}"
        )
    if field_type not in ("integer", "real"):
        _fail(
            f"{path} 格式头不支持：仅接受 integer 或 real 字段，"
            f"得到 {field_type!r}"
        )
    if symmetry != "general":
        _fail(
            f"{path} 格式头不支持：仅接受 general 对称性，得到 {symmetry!r}"
        )

    # 2) 跳过注释、找到尺寸行
    body_index = 1
    dimensions: Optional[List[str]] = None
    while body_index < len(lines):
        stripped = lines[body_index].strip()
        body_index += 1
        if stripped == "":
            continue
        if stripped.startswith("%"):
            continue
        dimensions = stripped.split()
        break
    if dimensions is None:
        _fail(f"{path} 缺少维度声明行（rows columns entries）")
    if len(dimensions) != 3:
        _fail(
            f"{path} 维度声明行需要 3 个整数（rows columns entries），"
            f"得到 {dimensions!r}"
        )
    dims: List[int] = []
    for label, token in zip(("rows", "columns", "entries"), dimensions):
        if not _is_decimal_uint(token) or int(token) < 0:
            _fail(f"{path} 维度声明 {label} 不是非负整数：{token!r}")
        dims.append(int(token))
    n_rows, n_cols, n_entries = dims

    # 3) 逐行解析坐标元素
    # entries 只存非零值；seen_coords 记录全部已出现坐标（含显式零），
    # 以便对零值重复坐标同样报“重复坐标”
    entries: Dict[Tuple[int, int], int] = {}
    seen_coords = set()
    entry_no = 0
    data_seen = 0
    # lines[body_index] 即维度行之后的第一行，其 1 基行号为 body_index + 1
    for line_no, raw_line in enumerate(lines[body_index:], start=body_index + 1):
        stripped = raw_line.strip()
        if stripped == "" or stripped.startswith("%"):
            continue
        entry_no += 1
        parts = stripped.split()
        if len(parts) != 3:
            _fail(
                f"{path} 第 {line_no} 行数据需要 3 列"
                f"（row column value），得到 {len(parts)} 列"
            )
        row_tok, col_tok, val_tok = parts
        if not _is_decimal_uint(row_tok) or not _is_decimal_uint(col_tok):
            _fail(
                f"{path} 第 {line_no} 行坐标不是正整数："
                f"{row_tok!r}, {col_tok!r}"
            )
        row_idx = int(row_tok)
        col_idx = int(col_tok)
        if row_idx < 1 or row_idx > n_rows:
            _fail(
                f"{path} 第 {entry_no} 个数据元素行索引 {row_idx} 越界"
                f"（声明行数 {n_rows}）"
            )
        if col_idx < 1 or col_idx > n_cols:
            _fail(
                f"{path} 第 {entry_no} 个数据元素列索引 {col_idx} 越界"
                f"（声明列数 {n_cols}）"
            )
        value = _parse_nonnegative_integer(val_tok, field_type, entry_no)
        key = (row_idx, col_idx)
        if key in seen_coords:
            _fail(
                f"{path} 出现重复坐标（行 {row_idx}、列 {col_idx}）"
            )
        seen_coords.add(key)
        data_seen += 1
        if value is not None:
            entries[key] = value

    if data_seen != n_entries:
        _fail(
            f"{path} 实际数据元素 {data_seen} 个与声明 {n_entries} 个不一致"
        )

    return n_rows, n_cols, entries


def read_mtx_directory(directory: str) -> ExpressionMatrix:
    """读取并严格校验一个 10x MatrixMarket 目录。"""
    if directory is None or directory == "":
        _fail("输入路径为空")
    if not os.path.exists(directory):
        _fail(f"MTX 输入目录不存在：{directory}")
    if not os.path.isdir(directory):
        _fail(f"MTX 输入路径不是目录：{directory}")

    # 先只解析三个文件名并校验“同为压缩或同为未压缩”，
    # 使布局错误先于任何文件内容错误暴露
    matrix_actual, matrix_gz = _resolve_name(directory, MATRIX_NAME)
    barcodes_actual, barcodes_gz = _resolve_name(directory, BARCODES_NAME)
    features_actual, features_gz = _resolve_name(directory, FEATURES_NAME)
    if not (matrix_gz == barcodes_gz == features_gz):
        _fail(
            f"MTX 三个输入文件必须同为未压缩或同为 gzip，当前混用："
            f"{matrix_actual}、{barcodes_actual}、{features_actual}"
        )

    matrix_raw, matrix_text = _read_named_file(
        directory, matrix_actual, compressed=matrix_gz
    )
    barcodes_raw, barcodes_text = _read_named_file(
        directory, barcodes_actual, compressed=barcodes_gz
    )
    features_raw, features_text = _read_named_file(
        directory, features_actual, compressed=features_gz
    )

    cell_ids = _read_id_lines(
        barcodes_text,
        os.path.join(directory, barcodes_actual),
        first_column_only=False,
        kind="细胞",
    )
    gene_ids = _read_id_lines(
        features_text,
        os.path.join(directory, features_actual),
        first_column_only=True,
        kind="基因",
    )
    if not cell_ids:
        _fail(f"{barcodes_actual} 没有任何非空细胞 ID 行")
    if not gene_ids:
        _fail(f"{features_actual} 没有任何非空基因 ID 数据行")

    n_rows, n_cols, entries = _parse_matrix(
        matrix_text, os.path.join(directory, matrix_actual)
    )
    if n_rows != len(gene_ids):
        _fail(
            f"{matrix_actual} 声明行数 {n_rows} 与 {features_actual} 基因数 "
            f"{len(gene_ids)} 不一致"
        )
    if n_cols != len(cell_ids):
        _fail(
            f"{matrix_actual} 声明列数 {n_cols} 与 {barcodes_actual} 细胞数 "
            f"{len(cell_ids)} 不一致"
        )

    # 以基因/ID 行序展开为稠密计数矩阵，缺失坐标即零
    counts: List[List[int]] = [[0] * n_cols for _ in range(n_rows)]
    total = 0
    for (row_idx, col_idx), value in entries.items():
        counts[row_idx - 1][col_idx - 1] = value
        total += value

    files = [
        InputFile(name=matrix_actual, sha256=hashlib.sha256(matrix_raw).hexdigest()),
        InputFile(name=barcodes_actual, sha256=hashlib.sha256(barcodes_raw).hexdigest()),
        InputFile(name=features_actual, sha256=hashlib.sha256(features_raw).hexdigest()),
    ]
    return ExpressionMatrix(
        gene_ids=gene_ids,
        cell_ids=cell_ids,
        counts=counts,
        sha256=files[0].sha256,
        path=directory,
        total_counts=total,
        input_format="mtx",
        files=files,
    )

from .cli import main

if __name__ == "__main__":
    raise SystemExit(main())

